#!/usr/bin/env python3
"""Generate compiled faction baselines from authenticated Mainline DB2 CSVs."""
import csv
import hashlib
import json
import sys
from pathlib import Path

source, output = map(Path, sys.argv[1:3])
factions_path = source / 'Faction.csv'
races_path = source / 'ChrRaces.csv'
with factions_path.open() as stream:
    factions = list(csv.DictReader(stream))
with races_path.open() as stream:
    races = list(csv.DictReader(stream))
lines = [
    '// Generated by scripts/import_reputation_baselines.py; do not edit.',
    f'// Source build {source.name}.',
    f'// Faction SHA256 {hashlib.sha256(factions_path.read_bytes()).hexdigest()}.',
    f'// ChrRaces SHA256 {hashlib.sha256(races_path.read_bytes()).hexdigest()}.',
    'pub const FACTIONS: &[(u32, &str, [(u64, u32, i32); 4])] = &[',
]
for row in sorted(factions, key=lambda row: int(row['ID'])):
    if int(row['ReputationIndex']) < 0:
        continue
    rules = []
    for index in range(4):
        low = int(row[f'ReputationRaceMasks{index}_0']) & 0xffffffff
        high = int(row[f'ReputationRaceMasks{index}_1']) & 0xffffffff
        mask = low | high << 32
        class_mask = int(row[f'ReputationClassMask_{index}']) & 0xffffffff
        value = int(row[f'ReputationBase_{index}'])
        rules.append(f'({mask}, {class_mask}, {value})')
    name = json.dumps(row['Name_lang'], ensure_ascii=False)
    lines.append(f'    ({row["ID"]}, {name}, [{", ".join(rules)}]),')
lines += ['];', '', 'pub const RACE_BITS: &[(u8, u32)] = &[']
for row in sorted(races, key=lambda row: int(row['ID'])):
    bit = int(row['PlayableRaceBit'])
    if bit >= 0:
        if bit >= 64:
            raise ValueError(f'Race{row["ID"]} bit{bit} exceeds Faction mask')
        lines.append(f'    ({row["ID"]}, {bit}),')
lines += ['];', '']
output.write_text('\n'.join(lines))
